return function(services: IServiceCollection, protocolImplemetionsFolder: Instance)
	services:AddSingleton("IProtoImplementionsProvider", function()
		return function()
			local implementions = {}
			assert(protocolImplemetionsFolder, "protocolImplemetionsFolder not provided")
			for _, moduleScript in protocolImplemetionsFolder:GetChildren() do
				implementions[moduleScript.Name] = moduleScript
			end
			return implementions
		end
	end)
end
